// Fail fast, before any backup work, on the settings that ship as placeholders.
//
// you@example.com is a reserved domain: mail servers accept it and discard it,
// so the run would go green and the report would never arrive. Stopping here
// costs one failed run and explains itself.
const s = $input.first().json;
const problems = [];

const email = String(s.notify_email || '').trim();
if (!email) {
  problems.push('notify_email is empty. Set it to the address the report should go to.');
} else if (email.toLowerCase() === 'you@example.com') {
  problems.push('notify_email is still the placeholder you@example.com. Set it to your own address - '
    + 'that domain is reserved, so the report would be accepted and thrown away.');
}

// The report is sent FROM this address. There is no fallback to notify_email:
// sending as the recipient's own address is refused by some mail servers
// (measured on the MySQL template's relay), and then no report ever arrives.
const from = String(s.notify_from || '').trim();
if (!from) {
  problems.push('notify_from is empty. Set it to an address your SMTP account is allowed to send from - '
    + 'the report is sent from this address.');
}

const bucket = String(s.s3_bucket || '').trim();
if (!bucket) {
  problems.push('s3_bucket is empty. Set it to the S3 bucket the zone files should go to.');
} else if (bucket.toLowerCase() === 'your-backup-bucket') {
  problems.push('s3_bucket is still the placeholder your-backup-bucket. Set it to your own bucket.');
}

const prefix = String(s.s3_prefix || '').trim();
if (!prefix) {
  problems.push('s3_prefix is empty. Set it to a folder used only by these backups.');
} else if (prefix.startsWith('/') || prefix.endsWith('/')) {
  problems.push('s3_prefix must not start or end with a slash - the workflow adds its own. '
    + 'A doubled slash lists nothing, so retention would silently stop working.');
}

const days = Number(s.retention_days);
if (!Number.isInteger(days) || days < 1) {
  problems.push('retention_days must be a whole number of days, 1 or more.');
}
const keep = Number(s.keep_at_least);
if (!Number.isInteger(keep) || keep < 1) {
  problems.push('keep_at_least must be a whole number, 1 or more. It is how many of the newest '
    + 'copies of each zone are never deleted.');
}

// One line, and no colon before the list. n8n shows a Code node error as
// "Unknown error" and keeps only the text before the first colon as its
// description when the message is multi-line, so the list a user needs to
// read was being dropped (measured, execution 93). Numbered problems on a
// single line survive intact.
if (problems.length) {
  throw new Error(`Backup settings needs ${problems.length} fix${problems.length > 1 ? 'es' : ''} - `
    + problems.map((p, i) => `(${i + 1}) ${p}`).join(' '));
}
return $input.all();

// One item per zone to back up, plus one per problem worth reporting.
// ALWAYS at least one item: an empty output stops the run before the report,
// and a backup that goes silent cannot be told apart from one that works.
const s = $('Backup settings').first().json;
const norm = (z) => String(z || '').trim().toLowerCase().replace(/\.$/, '');
const wanted = String(s.zones || '').split(/[\s,]+/).map(norm).filter(Boolean);
const message = (e) => typeof e === 'string' ? e : (e.message || JSON.stringify(e));
// Cloudflare puts its own, readable reason inside a JSON body in the error text.
// Sometimes that body arrives escaped inside a quoted string, so try both forms,
// and include the more specific error_chain messages when Cloudflare gives them.
const cloudflareReason = (text) => {
  const raw = String(text || '');
  for (const s of [raw, raw.replace(/\\"/g, '"')]) {
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');
    if (a < 0 || b < a) continue;
    try {
      const body = JSON.parse(s.slice(a, b + 1));
      const msgs = [];
      for (const x of body.errors || []) {
        if (x.message) msgs.push(x.message);
        for (const c of x.error_chain || []) if (c.message) msgs.push(c.message);
      }
      if (msgs.length) return msgs.join('; ');
    } catch (e) { /* not this form */ }
  }
  return '';
};
const refused = (e) => {
  const status = e && typeof e === 'object' && e.statusCode ? ` (HTTP ${e.statusCode})` : '';
  const text = typeof e === 'string' ? e : [e.error, e.description, e.message].filter(Boolean).join(' ');
  return 'Cloudflare refused the zone list' + status + ': '
    + (cloudflareReason(text) || String(message(e)).slice(0, 300));
};

const byId = new Map();
for (const page of $input.all()) {
  const body = page.json || {};
  if (body.error) {
    return [{ json: { zone_name: '(zone list)', problem: refused(body.error) } }];
  }
  if (body.success === false) {
    return [{ json: { zone_name: '(zone list)', problem: 'Cloudflare refused the zone list: '
      + (cloudflareReason(JSON.stringify(body)) || JSON.stringify(body.errors || []).slice(0, 300)) } }];
  }
  for (const z of body.result || []) byId.set(z.id, z);
}
const visible = [...byId.values()];

const out = [];
for (const z of visible) {
  if (wanted.length && !wanted.includes(norm(z.name))) continue;
  out.push({ json: { zone_id: z.id, zone_name: norm(z.name), name_servers: z.name_servers || [] } });
}
const seen = new Set(visible.map((z) => norm(z.name)));
for (const name of wanted) {
  if (!seen.has(name)) {
    out.push({ json: { zone_name: name, problem: 'this token cannot see the zone. Check the spelling '
      + 'in Backup settings, and that the token includes this zone.' } });
  }
}
if (out.length === 0) {
  out.push({ json: { zone_name: '(none)', none: true, problem: 'no zones were found. The token can see '
    + 'no zones at all - check its Zone Resources in the Cloudflare dashboard.' } });
}
return out;

// Count the records in the exported file and compare with Cloudflare's own count.
//
// The two are NOT expected to be equal. The export adds records Cloudflare
// manages itself and does not list as DNS records: the SOA, and an NS record
// for each Cloudflare-assigned nameserver at the zone apex. Measured on a live
// zone: 22 records in the file, 19 in the API, the difference exactly 1 SOA +
// 2 NS. A plain 'file equals API' check would call every good backup broken.
const zone = $('One zone at a time').first().json;
const s = $('Backup settings').first().json;
const text = String($('Export the zone file').first().json.zone_file || '');
const apiCount = Number((($input.first().json || {}).result_info || {}).total_count);

const fqdn = (n) => String(n || '').toLowerCase().replace(/\.?$/, '.');
const apex = fqdn(zone.zone_name);
const cfNameservers = new Set((zone.name_servers || []).map(fqdn));

// Strip a comment, but not a ';' inside a quoted TXT value (DMARC and SPF have them).
const stripComment = (line) => {
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '\\') { i++; continue; }
    if (c === '"') quoted = !quoted;
    else if (c === ';' && !quoted) return line.slice(0, i);
  }
  return line;
};
const tokens = (line) => line.match(/"(?:[^"\\]|\\.)*"|\S+/g) || [];

// Brackets group a record split over several lines, e.g. SOA ( ... ). Only
// brackets OUTSIDE quotes count: a TXT value such as "see (docs" is text, and
// counting its bracket swallowed every record after it (found 2026-10-09).
const unquotedParens = (line) => {
  let quoted = false;
  let depth = 0;
  let out = '';
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '\\') { out += c + (line[i + 1] || ''); i++; continue; }
    if (c === '"') quoted = !quoted;
    if (!quoted && (c === '(' || c === ')')) { depth += c === '(' ? 1 : -1; out += ' '; continue; }
    out += c;
  }
  return { depth, out };
};

const lines = [];
let pending = '';
for (const raw of text.split(/\r?\n/)) {
  const line = stripComment(raw).trim();
  if (!line) continue;
  pending = pending ? pending + ' ' + line : line;
  const { depth, out } = unquotedParens(pending);
  if (depth > 0) continue;   // the record continues on the next line
  lines.push(out);
  pending = '';
}

let inFile = 0;
let addedByCloudflare = 0;
const types = {};
let origin = apex;
for (const line of lines) {
  const t = tokens(line);
  if (t[0] && t[0].toUpperCase() === '$ORIGIN') { origin = fqdn(t[1]); continue; }
  if (t[0] && t[0].startsWith('$')) continue;
  const at = t.findIndex((x) => x.toUpperCase() === 'IN');
  if (at < 0 || !t[at + 1]) continue;
  const type = t[at + 1].toUpperCase();
  const name = t[0] === '@' ? origin : fqdn(t[0]);
  inFile++;
  types[type] = (types[type] || 0) + 1;
  if (type === 'SOA' && name === apex) addedByCloudflare++;
  else if (type === 'NS' && name === apex && cfNameservers.has(fqdn(t[at + 2]))) addedByCloudflare++;
}
const records = inFile - addedByCloudflare;
const matches = Number.isFinite(apiCount) && records === apiCount;

if (inFile === 0) {
  throw new Error(`the export for ${zone.zone_name} contained no records at all - nothing was uploaded`);
}

const day = new Date().toISOString().slice(0, 10);   // UTC, so a run near midnight is stable
const key = `${s.s3_prefix}/${zone.zone_name}/${day}.zone`;
return [{
  json: { zone_name: zone.zone_name, key, records, api_records: apiCount,
    added_by_cloudflare: addedByCloudflare, matches, types },
  binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'),
    mimeType: 'text/plain', fileName: `${zone.zone_name}-${day}.zone`, fileExtension: 'zone' } },
}];

// One uniform result for a zone that was uploaded, carrying the list of its
// existing copies for the retention step after the loop.
const check = $('Check the zone file').first().json;
const existing = [];
let listError = null;
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.error) listError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error));
  else if (j.Key) existing.push(j.Key);
}
return [{ json: { zone: check.zone_name, ok: true, key: check.key, records: check.records,
  api_records: check.api_records, added_by_cloudflare: check.added_by_cloudflare,
  matches: check.matches, existing, list_error: listError } }];

// One uniform result for a zone that was NOT backed up, whichever step failed.
//
// The report names the STEP, because the raw messages do not. A missing S3
// bucket comes back as "The resource you are requesting could not be found",
// word for word what Cloudflare says for a bad zone, so without the step a
// reader cannot tell which service to go and fix.
const zone = (() => { try { return $('One zone at a time').first().json || {}; } catch (e) { return {}; } })();
const steps = {
  'Export the zone file': 'exporting the zone from Cloudflare',
  'Count records in Cloudflare': 'counting the zone\'s records in Cloudflare',
  'Check the zone file': 'checking the exported file',
  'Upload to S3': 'uploading to S3 - check s3_bucket and the AWS credential',
};
const from = (() => { try { return $prevNode.name; } catch (e) { return ''; } })();

// Cloudflare puts its own, readable reason inside a JSON body in the error text.
// Sometimes that body arrives escaped inside a quoted string, so try both forms,
// and include the more specific error_chain messages when Cloudflare gives them.
const cloudflareReason = (text) => {
  const raw = String(text || '');
  for (const s of [raw, raw.replace(/\\"/g, '"')]) {
    const a = s.indexOf('{');
    const b = s.lastIndexOf('}');
    if (a < 0 || b < a) continue;
    try {
      const body = JSON.parse(s.slice(a, b + 1));
      const msgs = [];
      for (const x of body.errors || []) {
        if (x.message) msgs.push(x.message);
        for (const c of x.error_chain || []) if (c.message) msgs.push(c.message);
      }
      if (msgs.length) return msgs.join('; ');
    } catch (e) { /* not this form */ }
  }
  return '';
};

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let msg = j.problem;
  if (!msg && j.error) {
    const e = j.error;
    msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
    // n8n appends "[line N]" to a Code-node error. It points into our code, not
    // at anything the reader can fix, so drop it.
    msg = String(msg).replace(/\s*\[line \d+\]\s*$/, '');
    const reason = typeof e === 'object' ? cloudflareReason(e.description) : '';
    if (reason) msg = `${msg} (${reason})`;
    else if (e && typeof e === 'object' && e.description) msg += ' - ' + e.description;
    if (steps[from]) msg = `failed while ${steps[from]}: ${msg}`;
  }
  out.push({ json: { zone: zone.zone_name || j.zone_name || 'unknown', ok: false,
    none: Boolean(zone.none || j.none), error: String(msg || 'unknown error').slice(0, 300) } });
}
// A branch that emits nothing would end the loop silently.
if (out.length === 0) {
  out.push({ json: { zone: zone.zone_name || 'unknown', ok: false, error: 'no result returned for this zone' } });
}
return out;

// Single collection point for the loop: one result per zone, every iteration.
// The report reads every run of this node, not just the last one.
return $input.all();

// Decide which old copies to delete, per zone.
//
// Three rules, each one a way a backup has destroyed itself elsewhere:
// - Only files this workflow wrote are candidates: <prefix>/<zone>/YYYY-MM-DD.zone.
//   Anything else under the prefix is never touched.
// - The newest keep_at_least copies are kept however old they are, so a backup
//   that stops running for a month does not delete its last good copy.
// - Nothing is deleted for a zone whose backup failed TODAY.
//
// Age comes from the date in the file name, not S3's LastModified, which
// changes whenever an object is copied or restored.
const s = $('Backup settings').first().json;
const results = [];
for (let run = 0; run < 10000; run++) {
  let items;
  try { items = $('Record result').all(0, run); } catch (e) { break; }
  if (!items || items.length === 0) break;
  results.push(...items.map((i) => i.json || {}));
}
const days = Number(s.retention_days);
const keep = Number(s.keep_at_least);
const now = new Date();
const cutoff = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - days))
  .toISOString().slice(0, 10);

const expired = [];
for (const r of results) {
  if (!r.ok || r.list_error) continue;
  const base = `${s.s3_prefix}/${r.zone}/`;
  const dated = (r.existing || [])
    .filter((k) => k.startsWith(base))
    .map((k) => ({ key: k, day: (k.slice(base.length).match(/^(\d{4}-\d{2}-\d{2})\.zone$/) || [])[1] }))
    .filter((x) => x.day)
    .sort((a, b) => b.day.localeCompare(a.day));
  for (const x of dated.slice(keep)) {
    if (x.day < cutoff) expired.push({ json: { key: x.key, zone: r.zone, day: x.day } });
  }
}
// ALWAYS emit at least one item, or the report branch would not run.
if (expired.length === 0) return [{ json: { nothingExpired: true } }];
return expired;

// Count what actually happened, across EVERY iteration of the loop.
// $('node').all() defaults to the LAST run, which would report one zone only.
const s = $('Backup settings').first().json;
const results = [];
for (let run = 0; run < 10000; run++) {
  let items;
  try { items = $('Record result').all(0, run); } catch (e) { break; }
  if (!items || items.length === 0) break;
  results.push(...items.map((i) => i.json || {}));
}
const ok = results.filter((r) => r.ok);
const failed = results.filter((r) => !r.ok);
const none = failed.some((r) => r.none);
const mismatched = ok.filter((r) => !r.matches);

// The S3 delete node does not echo the key, so the names come from the node
// that chose them. Index i of the delete output is the result for index i.
const chosen = (() => { try { return $('Plan the clean-up').all().map((i) => i.json || {}).filter((j) => j.key); } catch (e) { return []; } })();
const outcomes = (() => { try { return $('Delete expired backup').all().map((i) => i.json || {}); } catch (e) { return []; } })();
const removed = [];
const notRemoved = [];
chosen.forEach((c, i) => {
  const o = outcomes[i];
  if (o && !o.error) removed.push(c.key);
  else notRemoved.push(`${c.key}: ${o && o.error ? (o.error.message || o.error) : 'no result'}`);
});

const lines = [];
if (none) {
  lines.push('NO ZONES WERE BACKED UP.', '');
}
lines.push(
  `Zones backed up: ${ok.length}`,
  `Zones failed: ${failed.filter((r) => !r.none).length}`,
  `Old copies removed: ${removed.length}`,
  `Bucket: ${s.s3_bucket}/${s.s3_prefix}`,
  `Retention: ${s.retention_days} days, always keeping the newest ${s.keep_at_least} of each zone`,
);
if (ok.length) {
  lines.push('', 'Backed up:');
  for (const r of ok) {
    const check = r.matches
      ? `${r.records} records, matches Cloudflare`
      : `${r.records} records, but Cloudflare reports ${r.api_records} - CHECK THIS FILE`;
    lines.push(`  - ${r.zone}: ${check}`, `      ${r.key}`);
    if (r.list_error) lines.push(`      old copies could not be listed, so none were removed: ${r.list_error}`);
  }
}
if (failed.length) {
  lines.push('', 'Not backed up:');
  for (const r of failed) lines.push(`  - ${r.zone}: ${r.error}`);
}
if (removed.length) {
  lines.push('', 'Removed past retention:', ...removed.map((k) => `  ${k}`));
}
if (notRemoved.length) {
  lines.push('', 'Could not remove:', ...notRemoved.map((k) => `  ${k}`));
}

let subject = `Cloudflare DNS backup: ${ok.length} ok, ${failed.filter((r) => !r.none).length} failed`;
if (removed.length) subject += `, ${removed.length} removed`;
if (mismatched.length) subject += `, ${mismatched.length} to check`;
// A bucket that has stopped being cleaned up must show in the subject, not
// only in the body, or it goes unnoticed until the bucket is full of copies.
if (ok.some((r) => r.list_error) || notRemoved.length) subject += ', cleanup failed';
if (none) subject = 'Cloudflare DNS backup: NO ZONES BACKED UP';
return [{ json: { subject, body: lines.join('\n'), succeeded: ok.length, failed: failed.length,
  removed: removed.length, mismatched: mismatched.length } }];
